<script setup lang="ts">
import { computed, ref } from 'vue';
import { catalog, currentMaterialVersion, journey } from '../journeyState';
import objects from '../../../mvp_foundation/examples/product-flow-fixtures.json';
const m=computed(()=>journey.material);
const notice=ref('');
const selectedCourses=ref<string[]>([]),adoptionBasis=ref(''),impactChecked=ref(false);
const candidates=computed(()=>journey.courses.filter(c=>c.version===1&&selectedCourses.value.includes(c.id)));
function adopt(){if(m.value.stage!=='published'||!impactChecked.value||!adoptionBasis.value.trim()||!candidates.value.length)return;for(const c of candidates.value){journey.adoptions.push({courseId:c.id,from:c.version,to:2,scope:[...c.units],basis:adoptionBasis.value.trim(),at:new Date().toISOString()});c.version=2;}selectedCourses.value=[];impactChecked.value=false;adoptionBasis.value='';notice.value='已指定所选合成空间采用 v2，原题单与历史记录保持当时版本；正式评价影响未执行。';}
const fingerprint=computed(()=>JSON.stringify([m.value.ocr,m.value.reviewed,m.value.standard,m.value.referenceReviewed,m.value.mappingReviewed,m.value.reason]));
const reviewReady=computed(()=>m.value.stage==='review'&&m.value.ocr.length===catalog.source_pages.length&&m.value.ocr.every(s=>s.trim())&&m.value.reviewed.every(Boolean)&&m.value.standard.trim()&&m.value.referenceReviewed&&m.value.mappingReviewed&&m.value.reason.trim());
const approved=computed(()=>reviewReady.value&&m.value.approved===fingerprint.value);
function begin(){if(m.value.stage!=='empty')return;m.value.taskId='IMPORT-DEMO-'+crypto.randomUUID().slice(0,8);m.value.stage='processing';m.value.audit.push('接收合成材料，建立同一处理任务；尚未执行真实识别。');}
function load(){if(m.value.stage!=='processing')return;m.value.ocr=catalog.source_pages.map(p=>p.ocr);m.value.stage='review';m.value.audit.push('载入预写识别结果，等待人工核对。');}
function approve(){if(!reviewReady.value)return;m.value.approved=fingerprint.value;m.value.audit.push('管理员记录对当前候选内容的审核批准。');notice.value='批准已绑定当前候选内容；任何修改都需要重新批准。';}
function publish(){if(!approved.value)return;m.value.stage='published';m.value.audit.push('合成教材与目标发布 v2；已创建空间保持原版本。');notice.value='目录已提供 v2。学生可创建新空间选用；现有空间仍采用原版本。';}
</script>
<template>
<main class="f-flow-page">
  <div class="f-content-heading"><div><span class="f-eyebrow">管理员 · 内容准备</span><h1>让教材成为可选用的学习内容</h1></div><span class="f-tag">合成目录 v{{ currentMaterialVersion }}</span></div>
  <details class="f-provenance"><summary>合成材料演示 · 未运行扫描识别或实际发布</summary><p>本页用两页自编文本代替扫描文件，走查处理、核对、审核、发布的衔接。不代表 PDF 上传、公式识别或服务端发布已经实现。v1 是预置可选目录，v2 是本次维护候选。</p></details>
  <section class="f-card"><h2>真实教材的准备情况</h2><ul><li>北师大版数学六年级上册：书目已知，具体版次、扫描材料与首批章节待确认。</li><li>校外内部教材：待提供。</li></ul><p>下面的面积学习册不是上述教材的内容或映射，不能据此标记真实教材就绪。</p></section>
  <section class="f-card"><h2>{{ catalog.material_title }}</h2><p>来源：作者为产品走查自编的两页文本。{{ catalog.reference_origin }}</p><button v-if="m.stage==='empty'" class="f-primary" @click="begin">载入合成材料任务</button><template v-else><p data-testid="import-task">处理任务：{{ m.taskId }}</p><p>当前状态：{{ {empty:'未接收',processing:'等待识别示例',review:'待核对与审核',published:'合成 v2 已发布'}[m.stage] }}。离开或刷新后仍查看同一任务。</p><button v-if="m.stage==='processing'" class="f-secondary" @click="load">载入该任务的识别示例</button></template></section>
  <template v-if="m.stage==='review'||m.stage==='published'">
    <section class="f-card"><h2>对照原材料核对</h2><article v-for="(p,i) in catalog.source_pages" :key="p.id" class="f-source-review"><div><span class="f-eyebrow">原材料第 {{ p.page }} 页 · {{ p.flagged?'识别有疑点':'未标疑点，仍需抽查' }}</span><h3>{{ p.title }}</h3><blockquote>{{ p.original }}</blockquote></div><div><label class="f-field">识别文本<textarea v-model="m.ocr[i]" :aria-label="`第${p.page}页识别文本`" :disabled="m.stage==='published'" @input="m.reviewed[i]=false"/></label><label><input type="checkbox" v-model="m.reviewed[i]" :disabled="m.stage==='published'"/> 已核对第 {{ p.page }} 页原材料</label></div></article></section>
    <section class="f-card"><h2>目标、映射与可用范围</h2><label class="f-field">学习目标与达标标准<textarea v-model="m.standard" aria-label="教材目标标准" :disabled="m.stage==='published'" @input="m.mappingReviewed=false"/></label><p>本例固定引用 PT-DEMO-AREA@1、ST-DEMO-AREA@1 与 KC-DEMO-AREA@1。对象定义可在下方核对；本页不声称自动建立映射。</p><details><summary>查看引用对象定义</summary><pre>{{ JSON.stringify({definition:objects.definition,supporting_objects:objects.supporting_objects},null,2) }}</pre></details><ul><li>第一章三角形面积：两节合成内容可供本轮讲解及检测走查。</li><li>第二章组合图形：仅示意章节结构，正式讲解及评价材料未准备，不进入检测题单。</li></ul><label class="f-check-line"><input type="checkbox" v-model="m.mappingReviewed" :disabled="m.stage==='published'"/> 已核对章节、目标及引用对象的适用关系</label><details><summary>查看自编参考依据</summary><ul><li v-for="q in catalog.questions" :key="q.id">{{ q.prompt }}<br/>{{ q.reference }}</li></ul></details><label class="f-check-line"><input type="checkbox" v-model="m.referenceReviewed" :disabled="m.stage==='published'"/> 已核对自编参考，并保留非原书答案的来源说明</label></section>
    <section class="f-card"><h2>审核与发布</h2><label class="f-field">审核依据<textarea v-model="m.reason" aria-label="教材审核依据" :disabled="m.stage==='published'" placeholder="记录核对了哪些原材料、映射和参考，以及剩余缺口。"/></label><p>同一管理员可以修改、审核和发布，操作仍分步记录。勾选表示人工确认，原型不能代替内容正确性判断。</p><div class="f-actions"><button class="f-secondary" :disabled="!reviewReady" @click="approve">批准当前教材候选</button><button class="f-primary" :disabled="!approved" @click="publish">发布合成教材 v2</button></div><p v-if="m.approved&&!approved&&m.stage==='review'" class="f-notice">候选内容或审核依据有变化，需要重新核对并批准。</p><p v-if="m.stage==='published'">新建空间可选 v2；发布本身不更新已有空间，各空间采用结果见下方。可在下方另行检查影响并指定采用；当前不模拟真实评价重处理。</p></section>
  </template>
  <section v-if="m.stage==='published'" class="f-card"><h2>检查影响后，指定已有空间采用</h2><p>这是更新既有采用关系，不替学生另选课程或章节。此前检测仍按当时采用的版本追溯。</p><p v-if="!journey.courses.length">尚无学生创建的合成空间。</p><label v-for="c in journey.courses" :key="c.id" class="f-check-line"><input type="checkbox" v-model="selectedCourses" :value="c.id" :disabled="c.version===2" @change="impactChecked=false"/> {{ c.name }} · 当前 v{{ c.version }} · 原章节 {{ c.units.join('、') }}</label><template v-if="candidates.length"><h3>本次影响范围</h3><ul><li v-for="c in candidates" :key="c.id">{{ c.name }}：从教材与目标 v1 更新至 v2；章节点保持。历史检测 {{ [...journey.examHistory,...(journey.exam.status==='ended'?[journey.exam]:[])].filter(e=>e.courseId===c.id).length }} 次保留原版。没有真实 Belief 可重算。</li></ul><label class="f-field">采用依据<textarea v-model="adoptionBasis" aria-label="课程采用依据" @input="impactChecked=false"/></label><label class="f-check-line"><input type="checkbox" v-model="impactChecked"/> 已核对所选空间、目标变更与保留范围</label><button class="f-primary" :disabled="!impactChecked||!adoptionBasis.trim()" @click="adopt">指定这些课程采用教材 v2</button></template><details v-if="journey.adoptions.length"><summary>查看课程采用记录</summary><ol><li v-for="(a,i) in journey.adoptions" :key="i">{{ a.courseId }}：v{{ a.from }} → v{{ a.to }}；范围 {{ a.scope.join('、') }}；{{ a.basis }}；{{ a.at }}</li></ol></details></section>
  <details v-if="m.audit.length" class="f-card"><summary>查看本次处理记录</summary><ol><li v-for="(a,i) in m.audit" :key="i">{{ a }}</li></ol></details><p v-if="notice" role="status" class="f-notice">{{ notice }}</p>
</main>
</template>
